#!/usr/bin/env bash
# install — make every script runnable from anywhere as a short command.
# Adds ~/.mackit-aliases to your ~/.zshrc. Run again any time to refresh.

set -u
DIR=$(cd "$(dirname "$0")" && pwd)
ALIASES="$HOME/.mackit-aliases"

chmod +x "$DIR"/*.sh

cat > "$ALIASES" <<EOF
# mackit — generated by install.sh, edit freely
alias cleanup="$DIR/mac-cleanup.sh"
alias health="$DIR/mac-health.sh"
alias ports="$DIR/ports.sh"
alias gsweep="$DIR/git-sweep.sh"
alias nuke="$DIR/node-nuke.sh"
alias devup="$DIR/dev-update.sh"
alias sstidy="$DIR/screenshot-tidy.sh"
EOF

grep -q 'mackit-aliases' "$HOME/.zshrc" 2>/dev/null || \
  printf '\n# mackit\n[ -f ~/.mackit-aliases ] && source ~/.mackit-aliases\n' >> "$HOME/.zshrc"

echo "✅ Installed. Open a new terminal (or run: source ~/.zshrc) and try:"
echo "   health · ports · cleanup · gsweep · nuke · devup · sstidy"
